import{H as e,_t as t,nt as n,rt as r}from"./chunks/framework.ByJSXnli.js";var i=JSON.parse(`{"title":"Operators by encoding","description":"","frontmatter":{},"headers":[],"relativePath":"reference/operators.md","filePath":"reference/operators.md"}`),a={name:`reference/operators.md`};function o(e,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[r(`<h1 id="operators-by-encoding" tabindex="-1">Operators by encoding <a class="header-anchor" href="#operators-by-encoding" aria-label="Permalink to “Operators by encoding”">​</a></h1><p>The operators of the core package, grouped by the candidate they work on. <a href="/guide/fundamentals/operators.html">Operators</a> explains the roles, and <a href="/guide/fundamentals/operator-composition.html">Operator composition</a> covers the operators that combine others.</p><h2 id="real-vectors" tabindex="-1">Real vectors <a class="header-anchor" href="#real-vectors" aria-label="Permalink to “Real vectors”">​</a></h2><p>Candidate <code>RealVector</code>, search space <code>BoundedRealVectorSearchSpace</code>.</p><div class="doc-table-scroll" tabindex="0"><table><thead><tr><th>Operator</th><th>Role</th><th>Does</th></tr></thead><tbody><tr><td><code>UniformDistributedCreator</code></td><td>Creator</td><td>Draws each element uniformly within the bounds</td></tr><tr><td><code>NormalDistributedCreator</code></td><td>Creator</td><td>Draws each element from a normal distribution, clamped to the bounds</td></tr><tr><td><code>AlphaBetaBlendCrossover</code></td><td>Crossover</td><td>Samples each element around both parents, wider towards the better one</td></tr><tr><td><code>SimulatedBinaryCrossover</code></td><td>Crossover</td><td>Simulated binary crossover (SBX)</td></tr><tr><td><code>SelfAdaptiveSimulatedBinaryCrossover</code></td><td>Crossover</td><td>The self-adaptive variant of SBX</td></tr><tr><td><code>SinglePointCrossover</code></td><td>Crossover</td><td>Joins the head of one parent with the tail of the other</td></tr><tr><td><code>GaussianMutator</code></td><td>Mutator</td><td>Adds normal noise to each element with a given rate and strength</td></tr><tr><td><code>PolynomialMutator</code></td><td>Mutator</td><td>Polynomial mutation, clamped to the bounds</td></tr></tbody></table></div><h2 id="integer-vectors" tabindex="-1">Integer vectors <a class="header-anchor" href="#integer-vectors" aria-label="Permalink to “Integer vectors”">​</a></h2><p>Candidate <code>IntegerVector</code>, search space <code>IntegerVectorSearchSpace</code>. The rounded operators compute a real value and round it into the bounds.</p><div class="doc-table-scroll" tabindex="0"><table><thead><tr><th>Operator</th><th>Role</th><th>Does</th></tr></thead><tbody><tr><td><code>UniformDistributedCreator</code></td><td>Creator</td><td>Draws each element uniformly within the bounds</td></tr><tr><td><code>NormalDistributedCreator</code></td><td>Creator</td><td>Draws each element from a rounded normal distribution</td></tr><tr><td><code>DiscreteCrossover</code></td><td>Crossover</td><td>Takes each element from a randomly chosen parent</td></tr><tr><td><code>SinglePointCrossover</code></td><td>Crossover</td><td>Joins the head of one parent with the tail of the other</td></tr><tr><td><code>RoundedAverageCrossover</code></td><td>Crossover</td><td>Averages the parents</td></tr><tr><td><code>RoundedBlendAlphaCrossover</code></td><td>Crossover</td><td>Samples each element from the parents&#39; range, widened by <code>Alpha</code></td></tr><tr><td><code>RoundedBlendAlphaBetaCrossover</code></td><td>Crossover</td><td>Like blend alpha, widened by <code>Alpha</code> and <code>Beta</code></td></tr><tr><td><code>RoundedHeuristicCrossover</code></td><td>Crossover</td><td>Steps from the worse parent past the better one</td></tr><tr><td><code>RoundedLocalCrossover</code></td><td>Crossover</td><td>A random weighted average per element</td></tr><tr><td><code>RoundedUniformArithmeticCrossover</code></td><td>Crossover</td><td>A weighted average at positions chosen with <code>Probability</code></td></tr><tr><td><code>UniformOnePositionMutator</code></td><td>Mutator</td><td>Replaces one element with a uniform value</td></tr><tr><td><code>UniformSomePositionsMutator</code></td><td>Mutator</td><td>Replaces each element with probability <code>Probability</code></td></tr><tr><td><code>RoundedNormalOnePositionMutator</code></td><td>Mutator</td><td>Adds rounded normal noise to one element</td></tr><tr><td><code>RoundedNormalAllPositionsMutator</code></td><td>Mutator</td><td>Adds rounded normal noise to every element</td></tr></tbody></table></div><h2 id="bool-vectors" tabindex="-1">Bool vectors <a class="header-anchor" href="#bool-vectors" aria-label="Permalink to “Bool vectors”">​</a></h2><p>Candidate <code>BoolVector</code>, search space <code>BoolVectorSearchSpace</code> or <code>FixedCardinalityBoolVectorSearchSpace</code>.</p><div class="doc-table-scroll" tabindex="0"><table><thead><tr><th>Operator</th><th>Role</th><th>Does</th></tr></thead><tbody><tr><td><code>RandomBoolVectorCreator</code></td><td>Creator</td><td>Sets each element with probability <code>SetProbability</code></td></tr><tr><td><code>BitUniformCrossover</code></td><td>Crossover</td><td>Takes each element from a randomly chosen parent</td></tr><tr><td><code>BitFlipMutator</code></td><td>Mutator</td><td>Flips each element with probability <code>FlipProbability</code></td></tr><tr><td><code>BitSwapMutator</code></td><td>Mutator</td><td>Swaps one set and one cleared element, so the count of set elements stays</td></tr></tbody></table></div><h2 id="permutations" tabindex="-1">Permutations <a class="header-anchor" href="#permutations" aria-label="Permalink to “Permutations”">​</a></h2><p>Candidate <code>Permutation</code>, search space <code>PermutationSearchSpace</code>.</p><div class="doc-table-scroll" tabindex="0"><table><thead><tr><th>Operator</th><th>Role</th><th>Does</th></tr></thead><tbody><tr><td><code>RandomPermutationCreator</code></td><td>Creator</td><td>Draws a uniformly random permutation</td></tr><tr><td><code>OrderCrossover</code></td><td>Crossover</td><td>Keeps a segment of one parent, fills the rest in the other&#39;s order</td></tr><tr><td><code>EdgeRecombinationCrossover</code></td><td>Crossover</td><td>Builds the child from edges both parents contain</td></tr><tr><td><code>SwapMutator</code></td><td>Mutator</td><td>Swaps two elements</td></tr><tr><td><code>InversionMutator</code></td><td>Mutator</td><td>Reverses a segment</td></tr></tbody></table></div><h2 id="expression-trees" tabindex="-1">Expression trees <a class="header-anchor" href="#expression-trees" aria-label="Permalink to “Expression trees”">​</a></h2><p>Candidate <code>ExpressionTree</code>, search space <code>ExpressionTreeSearchSpace</code>. <a href="/guide/domains/symbolic-expressions.html">Symbolic expressions</a> and <a href="/guide/domains/symbolic-regression.html">Symbolic regression</a> explain the settings and the numeric perturbations.</p><div class="doc-table-scroll" tabindex="0"><table><thead><tr><th>Operator</th><th>Role</th><th>Does</th></tr></thead><tbody><tr><td><code>GrowTreeCreator</code></td><td>Creator</td><td>Grows trees of mixed shape up to <code>MaximumDepth</code></td></tr><tr><td><code>FullTreeCreator</code></td><td>Creator</td><td>Builds trees whose leaves all sit at <code>Depth</code></td></tr><tr><td><code>RampedHalfAndHalfTreeCreator</code></td><td>Creator</td><td>Mixes grow and full trees over a range of depths</td></tr><tr><td><code>BalancedTreeCreator</code></td><td>Creator</td><td>Builds trees of a requested length breadth-first</td></tr><tr><td><code>ProbabilisticTreeCreator</code></td><td>Creator</td><td>Probabilistic tree creation (PTC2) for a requested length</td></tr><tr><td><code>SubtreeCrossover</code></td><td>Crossover</td><td>Replaces a subtree of one parent with a subtree of the other</td></tr><tr><td><code>SubtreeMutator</code></td><td>Mutator</td><td>Replaces a random subtree with a newly grown one</td></tr><tr><td><code>ShrinkSubtreeMutator</code></td><td>Mutator</td><td>Replaces an operation with a terminal</td></tr><tr><td><code>NodeReplacementMutator</code></td><td>Mutator</td><td>Replaces one symbol with another of the same arity</td></tr><tr><td><code>LocalPerturbationMutator</code></td><td>Mutator</td><td>Perturbs constants and variable weights</td></tr><tr><td><code>NumericParameterFittingRefiner</code></td><td>Refiner</td><td>Fits the numeric parameters of a symbolic regression model</td></tr></tbody></table></div><h2 id="any-candidate" tabindex="-1">Any candidate <a class="header-anchor" href="#any-candidate" aria-label="Permalink to “Any candidate”">​</a></h2><p>These operators work for every candidate type.</p><h3 id="selectors" tabindex="-1">Selectors <a class="header-anchor" href="#selectors" aria-label="Permalink to “Selectors”">​</a></h3><div class="doc-table-scroll" tabindex="0"><table><thead><tr><th>Operator</th><th>Does</th></tr></thead><tbody><tr><td><code>TournamentSelector</code></td><td>Picks the best of <code>TournamentSize</code> random candidates</td></tr><tr><td><code>ProportionalSelector</code></td><td>Picks in proportion to quality</td></tr><tr><td><code>LinearRankSelector</code></td><td>Picks in proportion to rank</td></tr><tr><td><code>GeneralizedRankSelector</code></td><td>Picks by rank with a configurable <code>Pressure</code></td></tr><tr><td><code>RandomSelector</code></td><td>Picks uniformly</td></tr><tr><td><code>BestSelector</code></td><td>Picks the best candidates</td></tr><tr><td><code>WorstSelector</code></td><td>Picks the worst candidates</td></tr><tr><td><code>ParetoCrowdingTournamentSelector</code></td><td>Tournament by Pareto rank, then crowding distance</td></tr><tr><td><code>EliteSelector</code></td><td>Takes the best <code>Elites</code>, then asks another selector for the rest</td></tr><tr><td><code>NoSameMatesSelector</code></td><td>Asks another selector again when both parents are the same</td></tr><tr><td><code>GenderSpecificSelector</code></td><td>Pairs one candidate from each of two selectors</td></tr></tbody></table></div><h3 id="replacers" tabindex="-1">Replacers <a class="header-anchor" href="#replacers" aria-label="Permalink to “Replacers”">​</a></h3><div class="doc-table-scroll" tabindex="0"><table><thead><tr><th>Operator</th><th>Does</th></tr></thead><tbody><tr><td><code>ElitismReplacer</code></td><td>Keeps the best <code>Elites</code> of the previous population</td></tr><tr><td><code>PlusSelectionReplacer</code></td><td>Keeps the best of parents and offspring together</td></tr><tr><td><code>CommaSelectionReplacer</code></td><td>Keeps the best offspring only</td></tr><tr><td><code>ParetoCrowdingReplacer</code></td><td>Keeps candidates by Pareto rank, then crowding distance</td></tr></tbody></table></div><h3 id="evaluators-and-refiners" tabindex="-1">Evaluators and refiners <a class="header-anchor" href="#evaluators-and-refiners" aria-label="Permalink to “Evaluators and refiners”">​</a></h3><div class="doc-table-scroll" tabindex="0"><table><thead><tr><th>Operator</th><th>Role</th><th>Does</th></tr></thead><tbody><tr><td><code>ProblemEvaluator</code></td><td>Evaluator</td><td>Evaluates through the problem</td></tr><tr><td><code>CachingEvaluator</code></td><td>Evaluator</td><td>Reuses results for equal keys</td></tr><tr><td><code>LimitEvaluator</code></td><td>Evaluator</td><td>Returns a fallback objective after <code>MaxEvaluations</code></td></tr><tr><td><code>RepeatingEvaluator</code></td><td>Evaluator</td><td>Evaluates repeatedly and aggregates the results</td></tr><tr><td><code>RelativeQualityEvaluator</code></td><td>Evaluator</td><td>Normalizes against a best-known objective vector</td></tr><tr><td><code>RefinementEvaluator</code></td><td>Evaluator</td><td>Evaluates refined copies and discards them</td></tr><tr><td><code>NoChangeRefiner</code></td><td>Refiner</td><td>Returns the candidates unchanged</td></tr><tr><td><code>IteratedRefiner</code></td><td>Refiner</td><td>Applies a refiner to its own output</td></tr><tr><td><code>ImprovementCheckingRefiner</code></td><td>Refiner</td><td>Keeps a refinement only if a criterion counts it as an improvement</td></tr><tr><td><code>PipelineRefiner</code></td><td>Refiner</td><td>Applies refiners in order</td></tr></tbody></table></div><h3 id="terminators" tabindex="-1">Terminators <a class="header-anchor" href="#terminators" aria-label="Permalink to “Terminators”">​</a></h3><div class="doc-table-scroll" tabindex="0"><table><thead><tr><th>Operator</th><th>Stops when</th></tr></thead><tbody><tr><td><code>AfterIterationsTerminator</code></td><td>A number of iterations is reached</td></tr><tr><td><code>AfterElapsedTimeTerminator</code></td><td>A time span has passed</td></tr><tr><td><code>AfterOperatorCountTerminator</code></td><td>A counter reaches a count</td></tr><tr><td><code>AfterOperatorDurationTerminator</code></td><td>A duration reaches a time span</td></tr><tr><td><code>TargetTerminator</code></td><td>The best objective reaches a target</td></tr><tr><td><code>StagnationTerminator</code></td><td>The objective has not improved for a number of states</td></tr><tr><td><code>CancellationTokenTerminator</code></td><td>A token is canceled</td></tr><tr><td><code>AnyTerminator</code></td><td>Any child terminator fires</td></tr><tr><td><code>AllTerminator</code></td><td>All child terminators fire</td></tr><tr><td><code>NeverTerminator</code></td><td>Never</td></tr></tbody></table></div><h3 id="interceptors-mutators-crossovers-and-creators" tabindex="-1">Interceptors, mutators, crossovers and creators <a class="header-anchor" href="#interceptors-mutators-crossovers-and-creators" aria-label="Permalink to “Interceptors, mutators, crossovers and creators”">​</a></h3><div class="doc-table-scroll" tabindex="0"><table><thead><tr><th>Operator</th><th>Role</th><th>Does</th></tr></thead><tbody><tr><td><code>IdentityInterceptor</code></td><td>Interceptor</td><td>Returns the state unchanged</td></tr><tr><td><code>RemoveDuplicatesInterceptor</code></td><td>Interceptor</td><td>Removes duplicate candidates from the state</td></tr><tr><td><code>PipelineInterceptor</code></td><td>Interceptor</td><td>Applies interceptors in order</td></tr><tr><td><code>NoChangeMutator</code></td><td>Mutator</td><td>Returns the candidates unchanged</td></tr><tr><td><code>PipelineMutator</code></td><td>Mutator</td><td>Applies mutators in order</td></tr><tr><td><code>RandomCrossover</code></td><td>Crossover</td><td>Returns one parent unchanged, chosen at random</td></tr><tr><td><code>SelectFirstParentCrossover</code></td><td>Crossover</td><td>Returns the first parent</td></tr><tr><td><code>SelectSecondParentCrossover</code></td><td>Crossover</td><td>Returns the second parent</td></tr><tr><td><code>TransformedCrossover</code></td><td>Crossover</td><td>Crosses, then always applies a mutator</td></tr><tr><td><code>TransformedCreator</code></td><td>Creator</td><td>Creates, then always applies a mutator</td></tr><tr><td><code>PredefinedCandidatesCreator</code></td><td>Creator</td><td>Returns given candidates first, then asks another creator</td></tr></tbody></table></div>`,29)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};